import unittest


def prime_length(string):

    l = len(string)
    if l == 0 or l == 1:
        return False
    for i in range(2, l):
        if l % i == 0:
            return False
    return True

# Unit test for function prime_length
def test_prime_length():
    class TestPrimeLength(unittest.TestCase):

        def test_empty_string(self):
            self.assertFalse(prime_length(""))

        def test_single_character(self):
            self.assertFalse(prime_length("a"))

        def test_two_characters(self):
            self.assertTrue(prime_length("ab"))

        def test_three_characters(self):
            self.assertTrue(prime_length("abc"))

        def test_four_characters(self):
            self.assertFalse(prime_length("abcd"))

        def test_five_characters(self):
            self.assertTrue(prime_length("abcde"))

        def test_six_characters(self):
            self.assertFalse(prime_length("abcdef"))

        def test_seven_characters(self):
            self.assertTrue(prime_length("abcdefg"))

        def test_nine_characters(self):
            self.assertFalse(prime_length("a" * 9))

        def test_eleven_characters(self):
            self.assertTrue(prime_length("a" * 11))

        def test_twelve_characters(self):
            self.assertFalse(prime_length("a" * 12))

        def test_thirteen_characters(self):
            self.assertTrue(prime_length("a" * 13))

        def test_with_spaces(self):
            self.assertTrue(prime_length("hello world"))  # length 11

        def test_with_special_characters(self):
            self.assertTrue(prime_length("!@#"))  # length 3

        def test_with_numbers(self):
            self.assertFalse(prime_length("12345678"))  # length 8

    return unittest.TestLoader().loadTestsFromTestCase(TestPrimeLength)


if __name__ == "__main__":
    runner = unittest.TextTestRunner()
    runner.run(test_prime_length())
